from math import isqrt

def has_proper_divisor(n: int) -> bool:
    return any(n % d == 0 for d in range(2, n))

def trial_prime(n: int) -> bool:
    return n >= 2 and not has_proper_divisor(n)

def trial_prime_fast(n: int) -> bool:
    if n < 2:
        return False
    return all(n % d != 0 for d in range(2, isqrt(n) + 1))

for n in [2, 3, 4, 91, 97, 101, 149, 150]:
    assert trial_prime(n) == trial_prime_fast(n)
    print(n, trial_prime(n))
assert trial_prime(97) and trial_prime(101) and not trial_prime(91)
print('certified: 97, 101 prime; 91 = 7 x 13 composite')

